public class HelpFormatter_renderWrappedText_TriageGen0Test {

    @Test
    public void testRenderWrappedText_NoWrap() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 2;
        String text = "abcdefghij";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals(text, sb.toString());
    }

    @Test
    public void testRenderWrappedText_SingleLineWrap() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = new StringBuffer();
        int width = 5;
        int nextLineTabStop = 2;
        String text = "abcdefghij";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("abcd\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_MultiLineWrap() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = new StringBuffer();
        int width = 5;
        int nextLineTabStop = 2;
        String text = "abcdefghijabcdefghij";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        String expected = "abcd\nabcd\n";
        assertEquals(expected, sb.toString());
    }

    @Test
    public void testRenderWrappedText_EmptyText() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 2;
        String text = "";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("", sb.toString());
    }

    @Test
    public void testRenderWrappedText_NullText() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 2;
        String text = null;
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("", sb.toString());
    }

    @Test
    public void testRenderWrappedText_NegativeWidth() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = new StringBuffer();
        int width = -1;
        int nextLineTabStop = 2;
        String text = "abcdefghij";
        try {
            formatter.renderWrappedText(sb, width, nextLineTabStop, text);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // expected
        }
    }

    @Test
    public void testRenderWrappedText_NegativeNextLineTabStop() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = -1;
        String text = "abcdefghij";
        try {
            formatter.renderWrappedText(sb, width, nextLineTabStop, text);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // expected
        }
    }

    @Test
    public void testRenderWrappedText_NullBuffer() {
        HelpFormatter formatter = new HelpFormatter();
        StringBuffer sb = null;
        int width = 10;
        int nextLineTabStop = 2;
        String text = "abcdefghij";
        try {
            formatter.renderWrappedText(sb, width, nextLineTabStop, text);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // expected
        }
    }
}
